using System;
using UnityEngine;

namespace ESP.Presentation.Editor
{
    /// <summary>Run in the project VM with -executeMethod ESP.Presentation.Editor.CloudBlendChecks.Validate.</summary>
    public static class CloudBlendChecks
    {
        const int Width = 256, Height = 64, Count = Width * Height;
        static readonly Color32 Missing = new Color32(0, 0, 0, 0);
        // Fixed samples from the NASA MODIS_Cloud_Fraction palette, not generated by
        // the decoder under test: measured 0%, 50%, and 100% cloud fraction.
        static readonly Color32 Clear = new Color32(102, 0, 119, 255);
        static readonly Color32 Half = new Color32(0, 220, 0, 255);
        static readonly Color32 Full = new Color32(255, 0, 5, 255);

        public static void Validate()
        {
            ConstantField();
            ClearAndMissing();
            MissingAndInvalid();
            NewestValidInBothOrders();
            MissingFallbackAndSupport();
            BorderSmoothing();
            Debug.Log("ESP_CLOUD_BLEND_CHECKS_OK constant clear missing invalid newest fallback support");
        }

        static void ConstantField()
        {
            var blend = NewBlend(); var observed = new bool[Count];
            Require(blend.Add(Filled(Half), 0, observed, out int unknown) == Count && unknown == 0,
                "Constant valid field must decode every sample.");
            var result = blend.Finish();
            for (int i = 0; i < Count; i++)
            {
                Require(observed[i] && result[i].g == 255, "Full observation support must be retained.");
                Near(Fraction(result[i]), .5f, .005f, "Constant fraction changed.");
            }
        }

        static void ClearAndMissing()
        {
            var source = Filled(Missing); var observed = new bool[Count]; var blend = NewBlend();
            for (int y = 0; y < Height; y++)
            for (int x = 0; x < Width / 2; x++) source[y * Width + x] = Clear;
            Require(blend.Add(source, 0, observed, out int unknown) == Count / 2 && unknown == 0,
                "Measured clear sky must count as valid, not missing.");
            var result = blend.Finish(); int observedCount = 0;
            for (int i = 0; i < Count; i++)
            {
                if (observed[i]) observedCount++;
                Require(result[i].r == 0, "Clear observations must not acquire clouds.");
            }
            Require(observedCount == Count / 2, "Missing pixels must not be marked observed.");
            Require(result[(Height / 2) * Width + Width / 4].g == 255,
                "Interior clear observation must retain full support.");
            Require(result[(Height / 2) * Width + 3 * Width / 4].g == 0,
                "A broad unobserved region must retain zero support.");
        }

        static void MissingAndInvalid()
        {
            var source = Filled(Missing); var observed = new bool[Count]; var blend = NewBlend();
            source[0] = new Color32(192, 192, 192, 255); // Explicit NASA fill, never cloud.
            source[1] = new Color32(254, 17, 33, 255); // Unknown non-palette RGB.
            Require(blend.Add(source, 0, observed, out int unknown) == 0 && unknown == 1,
                "Fill must be missing; unknown opaque RGB must be reported.");
            foreach (Color32 pixel in blend.Finish())
                Require(pixel.r == 0 && pixel.g == 0, "Unobserved field must have zero density and support.");
            foreach (bool valid in observed) Require(!valid, "Invalid colors must never become observations.");
        }

        static void NewestValidInBothOrders()
        {
            foreach (bool reverse in new[] { false, true })
            {
                var blend = NewBlend(); var observed = new bool[Count];
                var older = Filled(Full); var newer = Filled(Clear);
                if (reverse)
                {
                    Require(blend.Add(older, 2, observed, out _) == Count, "Older samples initially contribute.");
                    Require(blend.Add(newer, 0, observed, out _) == Count, "Newer samples replace older samples.");
                }
                else
                {
                    Require(blend.Add(newer, 0, observed, out _) == Count, "Newer samples initially contribute.");
                    Require(blend.Add(older, 2, observed, out _) == 0, "Fully superseded older date must not contribute.");
                }
                foreach (Color32 pixel in blend.Finish())
                    Require(pixel.r == 0 && pixel.g == 255,
                        "Newest measured clear must win over older cloud in either insertion order.");
            }
        }

        static void MissingFallbackAndSupport()
        {
            var newer = Filled(Missing); var older = Filled(Missing);
            int row = (Height / 2) * Width;
            newer[row] = Half;
            newer[row + 1] = Clear;
            newer[row + 2] = new Color32(254, 17, 33, 255); // Unknown, not clear.
            older[row] = Full;
            older[row + 1] = Full;
            older[row + 2] = Full;
            older[row + 3] = Half;
            foreach (bool reverse in new[] { false, true })
            {
                var blend = NewBlend(); var observed = new bool[Count];
                if (reverse)
                {
                    blend.Add(older, 1, observed, out _);
                    blend.Add(newer, 0, observed, out int unknown);
                    Require(unknown == 1, "Unknown newer palette sample must be reported.");
                }
                else
                {
                    blend.Add(newer, 0, observed, out int unknown);
                    Require(unknown == 1, "Unknown newer palette sample must be reported.");
                    Require(blend.Add(older, 1, observed, out _) == 2, "Older date contributes only missing or unknown pixels.");
                }
                var result = blend.Finish();
                Require(result[row + 2].g > 0 && result[row + 3].g > 0,
                    "Older observations must supply unknown and missing newer pixels.");
                for (int i = 0; i < Count; i++)
                {
                    bool expected = i >= row && i <= row + 3;
                    Require(observed[i] == expected, "Coverage mask must contain only actual observations.");
                }
                Require(result[row + Width / 2].g == 0, "Feather must not fill distant gaps.");
            }
        }

        static void BorderSmoothing()
        {
            var newer = Filled(Missing); var older = Filled(Missing);
            for (int y = 0; y < Height; y++)
            for (int x = 0; x < Width; x++)
            {
                if (x < Width / 2) newer[y * Width + x] = Clear;
                else if (x < 3 * Width / 4) older[y * Width + x] = Full;
            }
            var observed = new bool[Count]; var blend = NewBlend();
            blend.Add(newer, 0, observed, out _); blend.Add(older, 1, observed, out _);
            var result = blend.Finish(); int row = (Height / 2) * Width;
            Require(result[row + Width / 4].r == 0 && result[row + Width / 4].g == 255,
                "Clear interior must remain clear.");
            Require(Fraction(result[row + Width / 2 - 1]) > 0 && Fraction(result[row + Width / 2]) < 1,
                "Cross-date boundary must blend on both sides.");
            int gap = row + 3 * Width / 4;
            Require(!observed[gap] && result[gap].g > 0, "Feather must not change observation mask.");
            Require(result[gap + 8].g > 0 && result[gap + 8].g < result[gap].g,
                "Feather must taper across several pixels.");
            Require(result[gap + 17].g == 0, "Feather must end beyond its sixteen-pixel radius.");
        }

        static CloudShell.ObservationBlend NewBlend() => new CloudShell.ObservationBlend(Width, Height);
        static Color32[] Filled(Color32 value)
        {
            var result = new Color32[Count];
            for (int i = 0; i < result.Length; i++) result[i] = value;
            return result;
        }
        static float Fraction(Color32 pixel) => pixel.g > 0 ? pixel.r / (float)pixel.g : 0;
        static void Near(float actual, float expected, float tolerance, string message)
            => Require(Mathf.Abs(actual - expected) <= tolerance, message + " actual=" + actual + " expected=" + expected);
        static void Require(bool condition, string message)
        {
            if (!condition) throw new InvalidOperationException("ESP cloud blend check: " + message);
        }
    }
}
